// 1. STORE & STATE MANAGEMENT
// ==========================================
class Store {
  constructor() {
    this.state = {
      songs: [],
      tags: [],
      songTags: [],
      audio: [],
      playlists: [],
      playlistItems: [],
      currentProfile: 'none', // ПО УМОЛЧАНИЮ: 'none' (Обычный пользователь / слушатель)
      currentTab: 'catalog',
      catalogMobileSubTab: 'songs', // 'songs' | 'setlist' (для мобильных экранов)
      currentSongId: null,
      currentPlaylistId: 'pl-temp',
      concertIndex: 0,
      activeAudio: null,
      isPlaying: false,
      currentTime: 0,
      duration: 0,
      isAutoScrolling: false,
      searchQuery: '',
      notation: 'H',
      theme: 'paper-brick',
      concertTheme: 'paper',
      concertFontSize: 1.8,
      storageType: 'indexeddb',
      playerSource: 'all'
    };
    this.listeners = new Set();
  }

  getState() { return this.state; }
  setState(patch) {
    this.state = Object.assign({}, this.state, patch);
    this.notify();
  }
  subscribe(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }
  notify() {
    for (const listener of this.listeners) listener(this.state);
  }
}

const store = new Store();

// ==========================================
// 2. STORAGE REPOSITORY
// ==========================================
class StorageRepository {
  constructor() {
    this.dbName = 'OfflineSongbookDB_v10';
    this.version = 10;
    this.db = null;
    this.fallbackStorage = false;
  }

  async init() {
    if (!('indexedDB' in window)) {
      this.fallbackStorage = true;
      return;
    }
    try {
      this.db = await new Promise((resolve, reject) => {
        const req = indexedDB.open(this.dbName, this.version);
        req.onupgradeneeded = (e) => {
          const db = e.target.result;
          if (!db.objectStoreNames.contains('songs')) db.createObjectStore('songs', { keyPath: 'id' });
          if (!db.objectStoreNames.contains('tags')) db.createObjectStore('tags', { keyPath: 'id' });
          if (!db.objectStoreNames.contains('songTags')) db.createObjectStore('songTags', { autoIncrement: true });
          if (!db.objectStoreNames.contains('audio')) db.createObjectStore('audio', { keyPath: 'id' });
          if (!db.objectStoreNames.contains('playlists')) db.createObjectStore('playlists', { keyPath: 'id' });
          if (!db.objectStoreNames.contains('playlistItems')) db.createObjectStore('playlistItems', { autoIncrement: true });
          if (!db.objectStoreNames.contains('playerQueue')) db.createObjectStore('playerQueue', { keyPath: 'id' });
          if (!db.objectStoreNames.contains('settings')) db.createObjectStore('settings', { keyPath: 'key' });
        };
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error);
      });
    } catch (e) {
      this.fallbackStorage = true;
    }
  }

  async saveBatch(storeName, items) {
    if (this.fallbackStorage || !this.db) {
      try { localStorage.setItem('songbook_' + storeName, JSON.stringify(items)); } catch (e) {}
      return;
    }
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction([storeName], 'readwrite');
      const os = tx.objectStore(storeName);
      os.clear();
      for (const item of items) os.put(item);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }

  async getAll(storeName) {
    if (this.fallbackStorage || !this.db) {
      const raw = localStorage.getItem('songbook_' + storeName);
      return raw ? JSON.parse(raw) : [];
    }
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction([storeName], 'readonly');
      const os = tx.objectStore(storeName);
      const req = os.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => reject(req.error);
    });
  }

  async saveSetting(key, val) {
    if (this.fallbackStorage || !this.db) {
      localStorage.setItem('setting_' + key, JSON.stringify(val));
      return;
    }
    const tx = this.db.transaction(['settings'], 'readwrite');
    tx.objectStore('settings').put({ key, val });
  }

  async getSetting(key) {
    if (this.fallbackStorage || !this.db) {
      const v = localStorage.getItem('setting_' + key);
      return v ? JSON.parse(v) : null;
    }
    return new Promise(res => {
      const tx = this.db.transaction(['settings'], 'readonly');
      const req = tx.objectStore('settings').get(key);
      req.onsuccess = () => res(req.result ? req.result.val : null);
      req.onerror = () => res(null);
    });
  }
}

const storage = new StorageRepository();

